"use client";
// Cyrus studio preferences, browser side: load the profile's copy once the studio mounts (server wins; when the profile has
// none yet, the browser's own copy becomes its first version) and save changes back, debounced, as a patch of only the keys
// that changed. Fails soft: offline or before the migration the studio keeps working from localStorage.
import { useEffect } from "react";
import { useStore } from "@/lib/cyrus/store";
import { parseStudioPrefs, type StudioPrefs } from "./index";

const URL_ = "/api/cyrus/studio-prefs";
const same = (a: [number, number] | undefined, b: [number, number] | undefined) => !!a && !!b && a[0] === b[0] && a[1] === b[1];

/** Keys that differ between what the profile has and what the studio shows now (null = removed). Pure; unit-tested. */
export function diffPrefs(synced: StudioPrefs, now: Pick<StudioPrefs, "layout" | "simple" | "more">) {
  const layout: Record<string, [number, number] | null> = {};
  for (const [k, v] of Object.entries(now.layout)) if (!same(synced.layout[k], v)) layout[k] = v;
  for (const k of Object.keys(synced.layout)) if (!(k in now.layout)) layout[k] = null;
  const more: Record<string, number | null> = {};
  for (const [k, v] of Object.entries(now.more)) if (synced.more[k] !== v) more[k] = v;
  for (const k of Object.keys(synced.more)) if (!(k in now.more)) more[k] = null;
  const patch: { layout?: typeof layout; more?: typeof more; simple?: boolean } = {};
  if (Object.keys(layout).length) patch.layout = layout;
  if (Object.keys(more).length) patch.more = more;
  if (synced.simple !== now.simple) patch.simple = now.simple;
  return patch;
}

export function useStudioPrefsSync() {
  useEffect(() => {
    let alive = true;
    let ready = false;
    let timer: number | undefined;
    let synced: StudioPrefs = parseStudioPrefs(null);

    const flush = async () => {
      timer = undefined;
      const s = useStore.getState();
      const patch = diffPrefs(synced, s);
      if (!Object.keys(patch).length) return;
      try {
        const r = await fetch(URL_, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(patch), cache: "no-store" });
        if (!r.ok) return;
        const j = (await r.json()) as { prefs?: unknown; saved?: boolean };
        if (j.saved && j.prefs) synced = parseStudioPrefs(j.prefs);
      } catch { /* offline: the browser copy stays, the next change retries */ }
    };
    const schedule = () => {
      if (!ready) return;
      if (timer !== undefined) window.clearTimeout(timer);
      timer = window.setTimeout(() => void flush(), 700);
    };

    (async () => {
      try {
        const r = await fetch(URL_, { cache: "no-store" });
        if (!r.ok || !alive) return;
        const j = (await r.json()) as { prefs?: unknown; stored?: boolean };
        if (!alive) return;
        const p = parseStudioPrefs(j.prefs);
        if (j.stored) {
          synced = p;
          useStore.getState().hydratePrefs({ layout: p.layout, simple: p.simple, more: p.more });
        }
        ready = true;
        schedule(); // not stored yet: pushes the browser's copy up as the profile's first version
      } catch { /* no profile copy: keep the browser's */ }
    })();

    const unsub = useStore.subscribe((s, prev) => {
      if (s.layout !== prev.layout || s.simple !== prev.simple || s.more !== prev.more) schedule();
    });
    const onHide = () => { if (document.visibilityState === "hidden" && timer !== undefined) { window.clearTimeout(timer); void flush(); } };
    document.addEventListener("visibilitychange", onHide);
    return () => {
      alive = false;
      unsub();
      document.removeEventListener("visibilitychange", onHide);
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, []);
}
EOF

