// Customer app gate (r39), SERVER ONLY. Fail closed: the switch (CYRUS_CUSTOMER_APP=1) AND the studio viewer gate
// (preview accounts until the studios open) must both say yes, else the route 404s as if it did not exist.
// Every page and every server action calls appViewer() itself; nothing trusts the layout alone.
import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { onCyrusHost } from "@/lib/auth";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { studioViewer } from "@/lib/cyrus/studios/deps";
import { customerAppEnabled, appHref, APP_BASE } from "@/lib/cyrus/app/flags";

export type AppViewer = { user: User; onCyrus: boolean; nxeon: string; href: (internalPath: string) => string };

export async function appViewerOrNull(): Promise<AppViewer | null> {
  if (!customerAppEnabled()) return null;
  const v = await studioViewer().catch(() => null);
  if (!v) return null;
  const onCyrus = await onCyrusHost();
  return { user: v.user, onCyrus, nxeon: bridgeConfig().nxeonOrigin, href: (p) => appHref(p, onCyrus) };
}

export async function appViewer(): Promise<AppViewer> {
  const v = await appViewerOrNull();
  if (!v) notFound();
  return v;
}

export const P = {
  home: APP_BASE, new: `${APP_BASE}/new`, projects: `${APP_BASE}/projects`, assets: `${APP_BASE}/assets`, servers: `${APP_BASE}/servers`, wallet: `${APP_BASE}/wallet`, account: `${APP_BASE}/account`,
  project: (rootId: string) => `${APP_BASE}/projects/${encodeURIComponent(rootId)}`,
};
/** The existing studio pages (same on both hosts: /dashboard/cyrus passes through on cyrus.my). */
export const studioHref = (buildId?: string | null, studio?: string) =>
  !buildId ? "/dashboard/cyrus" : studio ? `/dashboard/cyrus/${encodeURIComponent(buildId)}/studio/${studio}` : `/dashboard/cyrus/${encodeURIComponent(buildId)}`;
"use client";
// The customer app's rail (desktop) / tab bar (phone). Links are host-aware: on cyrus.my they use the public paths.
import { usePathname } from "next/navigation";
import { IconCard, IconHome, IconPlus, IconServer, IconStack, IconStudio, IconUser } from "./icons";

export type NavHrefs = { home: string; new: string; projects: string; assets: string; servers: string; wallet: string; studio: string; account: string };

export function AppNav({ hrefs }: { hrefs: NavHrefs }) {
  const path = usePathname() || "";
  const at = (k: keyof NavHrefs) => {
    const internal = { home: "/dashboard/cyrus/app", new: "/dashboard/cyrus/app/new", projects: "/dashboard/cyrus/app/projects", assets: "/dashboard/cyrus/app/assets", servers: "/dashboard/cyrus/app/servers", wallet: "/dashboard/cyrus/app/wallet", studio: "/dashboard/cyrus", account: "/dashboard/cyrus/app/account" }[k];
    if (k === "home") return path === internal || path === hrefs.home;
    if (k === "studio") return false;
    return path.startsWith(internal) || path.startsWith(hrefs[k]);
  };
  const item = (k: keyof NavHrefs, label: string, Icon: typeof IconHome, desk = false) => (
    <a key={k} href={hrefs[k]} className={`cx-nav-a${desk ? " cx-desk" : ""}`} aria-current={at(k) ? "page" : undefined} data-tour={`nav-${k}`}>
      <Icon />{label}
    </a>
  );
  return (
    <nav aria-label="Cyrus" style={{ display: "contents" }}>
      {item("home", "Home", IconHome)}
      {item("new", "New mod", IconPlus)}
      {item("projects", "Projects", IconStack)}
      {item("assets", "My assets", IconStack)}
      {item("servers", "Servers", IconServer, true)}
      {item("wallet", "Wallet", IconCard, true)}
      {item("studio", "Studio", IconStudio)}
      {item("account", "Account", IconUser)}
    </nav>
  );
}
"use client";

import { useEffect, useState } from "react";
import { CheckIcon, CloseIcon, MinusIcon, PlusIcon, RecenterIcon, SparkleIcon } from "@/components/cyrus/icons/ui";
import { cameraApi } from "@/lib/cyrus/camera";
import { useStore } from "@/lib/cyrus/store";

export function ZoomControls() {
  const [k, setK] = useState(1);
  const select = useStore((s) => s.select);
  useEffect(() => cameraApi.onZoom(setK), []);

  return (
    <div
      className="fixed bottom-6 z-20 hidden flex-col items-start gap-2 transition-[left] duration-500 md:flex"
      style={{ left: 20 }}
    >
      {/* v6: the "Hierarchy" legend that sat here is gone (owner, 2026-10-08). */}
      <div className="glass-soft flex items-center gap-0.5 rounded-xl p-1">
        <button type="button" onClick={() => cameraApi.zoomBy(1 / 1.25)} className="cy5-btn-ghost h-8 w-8" aria-label="Zoom out">
          <MinusIcon />
        </button>
        <span className="w-11 text-center font-mono text-[11px] tabular-nums text-cy-muted">{Math.round(k * 100)}%</span>
        <button type="button" onClick={() => cameraApi.zoomBy(1.25)} className="cy5-btn-ghost h-8 w-8" aria-label="Zoom in">
          <PlusIcon />
        </button>
        <span className="mx-0.5 h-5 w-px bg-cy-line" />
        <button type="button" onClick={() => select({ level: "core" })} className="cy5-btn-ghost h-8 w-8" aria-label="Recenter on the core" title="Recenter">
          <RecenterIcon />
        </button>
      </div>
    </div>
  );
}

export function Toasts() {
  const toasts = useStore((s) => s.toasts);
  const dismiss = useStore((s) => s.dismissToast);
  return (
    <div className="pointer-events-none fixed left-1/2 top-[76px] z-[70] flex w-[min(380px,calc(100cqw-32px))] -translate-x-1/2 flex-col gap-2" aria-live="polite">
      {toasts.map((t) => {
        const rgb = t.rgb ?? (t.tone === "error" ? "244 63 94" : t.tone === "success" ? "52 211 153" : "167 139 250");
        return (
          <div key={t.id} className="cy5-glass animate-rise tint pointer-events-auto flex items-start gap-3 rounded-2xl p-3.5" style={{ ["--c" as string]: rgb }}>
