"use client";
// Cyrus core studio: the navigation menu (feature/cyrus-studio-ux). One place, in the studio's own top bar, for
//   - the view switch (Studio constellation / Simple list; same data, saved to the profile),
//   - where else Cyrus lives (Home, New mod, Projects, Assets, Servers, Wallet, Account, Help),
//   - the way back: Nxeon portal when the studio is open inside it, Cyrus home + Back to Nxeon on cyrus.my.
// Host-aware: on cyrus.my the public short paths (/home, /projects ...), inside the Nxeon portal the /dashboard/cyrus/app ones.
// The customer-app links exist only when the server says that app is on (appOn); the studio itself never depends on it.
import { useEffect, useRef, useState } from "react";
import { useCyrusHostInfo } from "@/components/cyrus/host-shell/HostContext";
import { appHref, APP_BASE } from "@/lib/cyrus/app/flags";
import { HELP_BASE_INTERNAL, HELP_BASE_PUBLIC } from "@/lib/cyrus/help/paths";
import { useStore } from "@/lib/cyrus/store";

export type NavLink = { key: string; label: string; href: string; external?: boolean };

/** Pure: the menu's links for a host. Unit-tested (test/cyrus-studio-ux.test.ts). */
export function studioNavLinks(o: { onCyrus: boolean; nxeon: string; appOn: boolean; backHref?: string }): { go: NavLink[]; back: NavLink[] } {
  const h = (p: string) => appHref(p, o.onCyrus);
  const go: NavLink[] = [];
  if (o.appOn) {
    go.push(
      { key: "home", label: "Home", href: h(APP_BASE) },
      { key: "new", label: "New mod", href: h(`${APP_BASE}/new`) },
      { key: "projects", label: "Projects", href: h(`${APP_BASE}/projects`) },
      { key: "assets", label: "My assets", href: h(`${APP_BASE}/assets`) },
      { key: "servers", label: "Servers", href: h(`${APP_BASE}/servers`) },
      { key: "wallet", label: "Wallet", href: h(`${APP_BASE}/wallet`) },
      { key: "account", label: "Account", href: h(`${APP_BASE}/account`) },
    );
  }
  go.push({ key: "help", label: "Help", href: o.onCyrus ? HELP_BASE_PUBLIC : HELP_BASE_INTERNAL });
  const back: NavLink[] = [];
  if (o.onCyrus) {
    if (o.appOn) back.push({ key: "cyrus-home", label: "Back to Cyrus home", href: "/home" });
    back.push({ key: "nxeon", label: "Back to Nxeon", href: o.nxeon || "/", external: true });
  } else {
    back.push({ key: "portal", label: "Back to the Nxeon portal", href: o.backHref && o.backHref.startsWith("/dashboard") && !o.backHref.startsWith("/dashboard/cyrus") ? o.backHref : "/dashboard" });
  }
  return { go, back };
}

const Bars = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" aria-hidden><path d="M2.5 4.5h11M2.5 8h11M2.5 11.5h11" /></svg>
);

export function StudioNav({ appOn }: { appOn: boolean }) {
  const host = useCyrusHostInfo();
  const simple = useStore((s) => s.simple);
  const setSimple = useStore((s) => s.setSimple);
  const [open, setOpen] = useState(false);
  const [backHref, setBackHref] = useState<string | undefined>();
  const btn = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try { setBackHref(sessionStorage.getItem("nx-last-portal-path") ?? undefined); } catch { /* storage blocked */ }
  }, [open]);
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); setOpen(false); btn.current?.focus(); } };
    const onDown = (e: PointerEvent) => { const t = e.target as Node; if (!panel.current?.contains(t) && !btn.current?.contains(t)) setOpen(false); };
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("pointerdown", onDown, true);
    panel.current?.querySelector<HTMLElement>("a,button")?.focus();
    return () => { window.removeEventListener("keydown", onKey, true); window.removeEventListener("pointerdown", onDown, true); };
  }, [open]);

  const { go, back } = studioNavLinks({ onCyrus: host.onCyrus, nxeon: host.nxeon, appOn, backHref });
  const Item = ({ l }: { l: NavLink }) => (
    <a className="cyk-nav-item" href={l.href} {...(l.external ? { target: "_blank", rel: "noopener noreferrer" } : {})} onClick={() => setOpen(false)} data-nav={l.key}>
      {l.label}
      {l.external && <span aria-hidden className="cyk-nav-ext">↗</span>}
    </a>
  );

  return (
    <div className="cyk-nav-wrap pointer-events-auto">
      <button ref={btn} type="button" className="cyk-nav-btn" aria-haspopup="true" aria-expanded={open} aria-controls="cyk-nav-panel" aria-label="Menu" onClick={() => setOpen((o) => !o)} data-testid="studio-menu">
        <Bars />
      </button>
      {open && (
        <div ref={panel} id="cyk-nav-panel" className="cyk-nav-panel" role="menu" aria-label="Cyrus menu">
          <div className="cyk-nav-sec">View</div>
          <div className="cyk-seg" role="group" aria-label="Studio view">
            <button type="button" aria-pressed={!simple} onClick={() => setSimple(false)} data-testid="view-studio">Studio</button>
            <button type="button" aria-pressed={simple} onClick={() => setSimple(true)} data-testid="view-simple">Simple</button>
          </div>
          <p className="cyk-nav-hint">{simple ? "A plain list of your mods and the same prompt. Nothing is removed." : "The full map: branches you can drag, every control."}</p>
          <div className="cyk-nav-sec">Go to</div>
          {go.map((l) => <Item key={l.key} l={l} />)}
          <div className="cyk-nav-sep" />
          {back.map((l) => <Item key={l.key} l={l} />)}
        </div>
      )}
    </div>
  );
}
