"use client";
// Cyrus core studio, Simple view (feature/cyrus-studio-ux): the SAME mods, grouped by game and category as a plain list,
// plus the same prompt dock, preview panel, palette and token chip around it. It replaces only the constellation canvas;
// nothing about builds, installs or the panel changes, so no capability is lost by switching.
import { useMemo } from "react";
import { CATEGORY_BY_KEY } from "@/lib/cyrus/data";
import { useAllMods, useGames, useStore } from "@/lib/cyrus/store";
import type { Mod } from "@/lib/cyrus/types";

export function SimpleView() {
  const mods = useAllMods();
  const games = useGames();
  const select = useStore((s) => s.select);
  const selected = useStore((s) => s.selection.modId);
  const setSimple = useStore((s) => s.setSimple);
  const groups = useMemo(() => {
    const out: { id: string; name: string; cats: { key: string; label: string; mods: Mod[] }[] }[] = [];
    for (const g of games) {
      const gm = mods.filter((m) => m.gameId === g.id && !m.idea);
      if (!gm.length) continue;
      const byCat = new Map<string, Mod[]>();
      for (const m of [...gm].sort((a, b) => b.createdAt - a.createdAt)) byCat.set(m.category, [...(byCat.get(m.category) ?? []), m]);
      out.push({ id: g.id, name: g.name, cats: [...byCat].map(([key, ms]) => ({ key, label: CATEGORY_BY_KEY[key as keyof typeof CATEGORY_BY_KEY]?.label ?? key, mods: ms })) });
    }
    return out;
  }, [mods, games]);

  return (
    <main className="cyk-simple" aria-label="Your mods">
      <div className="cyk-simple-in">
        <h2 className="cyk-simple-h">Your mods</h2>
        <p className="cyk-simple-sub">Describe what you want in the box below, or open a mod to see it, change it and install it.</p>
        {groups.length === 0 ? (
          <div className="cyk-simple-empty">No mods yet. Describe your first one below.</div>
        ) : (
          groups.map((g) => (
            <section key={g.id} className="cyk-simple-game">
              <h3>{g.name}</h3>
              {g.cats.map((c) => (
                <div key={c.key} className="cyk-simple-cat">
                  <div className="cyk-simple-catname">{c.label}</div>
                  <ul>
                    {c.mods.map((m) => (
                      <li key={m.id}>
                        <button type="button" className="cyk-simple-mod" aria-current={selected === m.id ? "true" : undefined} onClick={() => select({ level: "mod", gameId: m.gameId, category: m.category, modId: m.id }, { openPanel: true })}>
                          <span className="cyk-simple-modname">{m.name}</span>
                          {m.real?.running ? <span className="cyk-simple-tag">Building</span> : m.real?.failed ? <span className="cyk-simple-tag is-bad">Failed</span> : m.library ? <span className="cyk-simple-tag">Library</span> : null}
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </section>
          ))
        )}
        <button type="button" className="cyk-simple-back" onClick={() => setSimple(false)}>Open the full studio map</button>
      </div>
    </main>
  );
}
