                        <button type="button" className="cyk-simple-mod" aria-current={selected === m.id ? "true" : undefined} onClick={() => select({ level: "mod", gameId: m.gameId, category: m.category, modId: m.id }, { openPanel: true })}>
                          <span className="cyk-simple-modname">{m.name}</span>
                          {m.real?.running ? <span className="cyk-simple-tag">Building</span> : m.real?.failed ? <span className="cyk-simple-tag is-bad">Failed</span> : m.library ? <span className="cyk-simple-tag">Library</span> : null}
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </section>
          ))
        )}
        <button type="button" className="cyk-simple-back" onClick={() => setSimple(false)}>Open the full studio map</button>
      </div>
    </main>
  );
}
