    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
  z-index: 2;
}
.cyrus-root .prompt-shell[data-active="true"]::before, .cyrus-root .prompt-shell[data-busy="true"]::before {
