/* ═══ CYRUS studio UX (feature/cyrus-studio-ux) ═══════════════════════════════════════════════
   1. cyk-*      the studio menu (StudioNav) and the Simple view (SimpleView), on the studio's own tokens;
   2. .cosmos[data-cy-stars]   the cyrus.my starfield backdrop (black, very faint stars, rare shooting stars);
   3. .cyrus-root[data-cy-skin="cyrus"]   the Cyrus skin: the landing's language (black and white, hairlines, blue to
      violet energy only on the one primary action, Space Grotesk + mono labels, crisp short motion) in place of the
      violet glass and aurora the studio inherited from the Nxeon portal. It re-points the SAME token names the whole
      studio already uses, so every component follows without being edited; layout and behaviour do not change.
   Everything hangs off .cyrus-root (or :root:has(.cyrus-root...) for the one strip the portal shell owns), so Nxeon's
   portal, admin and marketing are untouched (CLAUDE.md scoping rules). */

/* ───────── 1. menu ───────── */
.cyrus-root .cyk-nav-wrap { position: relative; flex: none; }
.cyrus-root .cyk-nav-btn {
  display: grid; place-items: center; width: 36px; height: 36px; border-radius: 12px;
  background: var(--surface-soft); border: 1px solid var(--line); color: var(--ink-2); cursor: pointer;
  transition: color .15s, border-color .15s;
}
.cyrus-root .cyk-nav-btn:hover, .cyrus-root .cyk-nav-btn[aria-expanded="true"] { color: var(--ink); border-color: var(--line-2); }
.cyrus-root .cyk-nav-panel {
  position: absolute; left: 0; top: 44px; z-index: 60; width: 248px; padding: 10px; border-radius: 16px;
  background: var(--solid); border: 1px solid var(--line-2); box-shadow: var(--panel-shadow);
  display: flex; flex-direction: column; gap: 2px; max-height: calc(100cqh - 80px); overflow: auto;
}
.cyrus-root .cyk-nav-sec { padding: 8px 8px 4px; font: 600 10px var(--font-jb), ui-monospace, monospace; letter-spacing: .16em; text-transform: uppercase; color: var(--faint); }
.cyrus-root .cyk-nav-hint { margin: 6px 8px 4px; font-size: 11.5px; line-height: 1.4; color: var(--muted); }
.cyrus-root .cyk-nav-item {
  display: flex; align-items: center; justify-content: space-between; height: 36px; padding: 0 10px; border-radius: 10px;
  font-size: 13.5px; color: var(--ink-2); text-decoration: none; transition: background .12s, color .12s;
}
.cyrus-root .cyk-nav-item:hover, .cyrus-root .cyk-nav-item:focus-visible { background: rgb(var(--glow) / 0.1); color: var(--ink); outline: none; }
.cyrus-root .cyk-nav-ext { color: var(--faint); font-size: 12px; }
.cyrus-root .cyk-nav-sep { height: 1px; margin: 6px 4px; background: var(--line); }
.cyrus-root .cyk-seg { display: grid; grid-template-columns: 1fr 1fr; gap: 2px; margin: 0 4px; padding: 3px; border-radius: 12px; background: rgb(var(--glow) / 0.07); border: 1px solid var(--line); }
.cyrus-root .cyk-seg button { height: 30px; border-radius: 9px; font-size: 13px; font-weight: 600; color: var(--muted); background: none; border: 0; cursor: pointer; }
.cyrus-root .cyk-seg button[aria-pressed="true"] { background: var(--ink); color: var(--bg); }

/* ───────── Simple view ───────── */
.cyrus-root .cyk-simple { position: absolute; inset: 64px 0 0 0; overflow: auto; padding: 8px 16px 220px; }
.cyrus-root .cyk-simple-in { max-width: 760px; margin: 0 auto; }
.cyrus-root .cyk-simple-h { font: 600 26px/1.15 var(--font-space), var(--font-inter), sans-serif; letter-spacing: -.02em; color: var(--ink); margin-top: 18px; }
.cyrus-root .cyk-simple-sub { margin-top: 6px; font-size: 14px; color: var(--muted); }
.cyrus-root .cyk-simple-empty { margin-top: 24px; padding: 28px; text-align: center; border-radius: 16px; border: 1px dashed var(--line-2); color: var(--muted); }
.cyrus-root .cyk-simple-game { margin-top: 26px; }
.cyrus-root .cyk-simple-game > h3 { font: 600 11px var(--font-jb), monospace; letter-spacing: .16em; text-transform: uppercase; color: var(--faint); }
.cyrus-root .cyk-simple-cat { margin-top: 12px; border-radius: 16px; background: var(--surface-soft); border: 1px solid var(--line); padding: 6px; }
.cyrus-root .cyk-simple-catname { padding: 8px 10px 4px; font-size: 12px; font-weight: 600; color: var(--muted); }
.cyrus-root .cyk-simple-cat ul { list-style: none; margin: 0; padding: 0; }
.cyrus-root .cyk-simple-mod { display: flex; width: 100%; align-items: center; gap: 10px; min-height: 44px; padding: 0 10px; border-radius: 10px; background: none; border: 0; cursor: pointer; text-align: left; color: var(--ink); }
.cyrus-root .cyk-simple-mod:hover, .cyrus-root .cyk-simple-mod[aria-current="true"] { background: rgb(var(--glow) / 0.1); }
.cyrus-root .cyk-simple-modname { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 500; }
.cyrus-root .cyk-simple-tag { font: 600 10.5px var(--font-jb), monospace; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-2); color: var(--muted); }
.cyrus-root .cyk-simple-tag.is-bad { color: rgb(244 63 94); border-color: rgb(244 63 94 / .4); }
.cyrus-root .cyk-simple-back { margin-top: 26px; font-size: 12.5px; color: var(--muted); background: none; border: 0; text-decoration: underline; cursor: pointer; }

/* ───────── 2. cyrus.my starfield ───────── */
