"use client";
// Per-browser preview of the Cyrus skin before it is switched on for everyone (CYRUS_STUDIO_SKIN): ?skin=cyrus turns it on
// and remembers it, ?skin=nxeon turns it off and forgets it. Without the param the stored choice, then the server default.
import { useLayoutEffect } from "react";

export const SKIN_KEY = "cyrus-skin";

export function SkinSwitch() {
  useLayoutEffect(() => {
    const root = document.querySelector<HTMLElement>(".cyrus-root");
    if (!root) return;
