// cyrus.my backdrop maths, PURE (unit-tested in test/cyrus-studio-ux.test.ts): how many stars, how faint, when the next
// shooting star comes. The canvas component only draws what these return.
export const STARFIELD = {
  maxStars: 240,
  areaPerStar: 8200,
  /** brightest a star may ever be: "very faint" is a hard ceiling, not a tuning hint */
  maxAlpha: 0.26,
  minAlpha: 0.05,
  /** shooting star every 20-50 s of VISIBLE time */
  shotMinMs: 20000,
  shotMaxMs: 50000,
  /** frame budget: 24 fps is plenty for a sky */
  frameMs: 1000 / 24,
} as const;

export function starCount(w: number, h: number): number {
  return Math.max(0, Math.min(STARFIELD.maxStars, Math.round((w * h) / STARFIELD.areaPerStar)));
}

/** Deterministic star list for a size and a random source (so a test can pin it). */
export function makeStars(w: number, h: number, rnd: () => number) {
  return Array.from({ length: starCount(w, h) }, () => {
    const big = rnd() < 0.04;
    return {
      x: rnd(),
      y: rnd(),
      r: big ? 0.7 + rnd() * 0.5 : 0.3 + rnd() * 0.4,
      a: STARFIELD.minAlpha + rnd() * (STARFIELD.maxAlpha - STARFIELD.minAlpha) * (big ? 1 : 0.7),
      tw: 0.2 + rnd() * 0.5,
      ph: rnd() * Math.PI * 2,
      d: 0.2 + rnd() * 0.8,
    };
  });
}

export const nextShotDelay = (rnd: () => number) => STARFIELD.shotMinMs + rnd() * (STARFIELD.shotMaxMs - STARFIELD.shotMinMs);

/** The star's alpha at time t (seconds); never above maxAlpha. `still` = reduced motion: no twinkle. */
export function starAlpha(a: number, tw: number, ph: number, t: number, still: boolean): number {
  const k = still ? 1 : 0.8 + 0.2 * Math.sin(t * tw + ph);
  return Math.min(STARFIELD.maxAlpha, a * k);
}
