"use client";
// cyrus.my studio backdrop: pure black, very faint stars, an occasional shooting star. Canvas 2D, no WebGL.
//  - prefers-reduced-motion: one static frame, no twinkle, no shooting stars, no animation loop at all;
//  - low CPU: 24 fps cap, ~200 dots, a single streak at most, redraw only while the tab is visible;
//  - hidden tab: the loop stops and resumes on return (visibilitychange), the shooting-star timer does not accrue.
import { useEffect, useRef } from "react";
import { camera } from "@/lib/cyrus/camera";
import { makeStars, nextShotDelay, starAlpha, STARFIELD } from "./starfield";

export function Starfield() {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // The black sky is dark by nature: while it shows, the studio is dark whatever the browser's saved theme says.
  useEffect(() => {
    const root = document.documentElement;
    const prev = root.getAttribute("data-theme");
    root.setAttribute("data-theme", "dark");
    return () => { if (prev) root.setAttribute("data-theme", prev); else root.removeAttribute("data-theme"); };
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let still = mq.matches;
    let W = 0, H = 0, dpr = 1;
    let stars = makeStars(0, 0, Math.random);
    let shot: { x: number; y: number; vx: number; vy: number; life: number } | null = null;
    let untilShot = nextShotDelay(Math.random);
    let raf = 0, last = 0;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const host = hostRef.current;
      W = host?.clientWidth || window.innerWidth;
      H = host?.clientHeight || window.innerHeight;
      canvas.width = Math.round(W * dpr);
      canvas.height = Math.round(H * dpr);
      canvas.style.width = `${W}px`;
      canvas.style.height = `${H}px`;
      stars = makeStars(W, H, Math.random);
      draw(performance.now());
    };

    const draw = (now: number) => {
      const t = now / 1000;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);
      for (const s of stars) {
        const px = (((s.x * W - camera.x * 0.06 * s.d * camera.k) % W) + W) % W;
        const py = (((s.y * H - camera.y * 0.06 * s.d * camera.k) % H) + H) % H;
        ctx.fillStyle = `rgb(235 240 255 / ${starAlpha(s.a, s.tw, s.ph, t, still)})`;
        ctx.beginPath();
        ctx.arc(px, py, s.r, 0, Math.PI * 2);
        ctx.fill();
      }
      if (shot) {
        const len = 0.16;
        const g = ctx.createLinearGradient(shot.x, shot.y, shot.x - shot.vx * len, shot.y - shot.vy * len);
        g.addColorStop(0, `rgb(235 240 255 / ${0.34 * shot.life})`);
        g.addColorStop(1, "rgb(235 240 255 / 0)");
        ctx.strokeStyle = g;
        ctx.lineWidth = 1;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(shot.x, shot.y);
        ctx.lineTo(shot.x - shot.vx * len, shot.y - shot.vy * len);
        ctx.stroke();
      }
    };

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dtMs = now - last;
      if (dtMs < STARFIELD.frameMs) return;
      last = now;
      const dt = Math.min(0.1, dtMs / 1000);
      if (!shot) {
        untilShot -= dt * 1000;
        if (untilShot <= 0) {
          const fromLeft = Math.random() < 0.5;
          shot = { x: fromLeft ? Math.random() * W * 0.5 : W * (0.5 + Math.random() * 0.5), y: Math.random() * H * 0.4, vx: (fromLeft ? 1 : -1) * (480 + Math.random() * 240), vy: 160 + Math.random() * 120, life: 1 };
          untilShot = nextShotDelay(Math.random);
        }
      } else {
        shot.x += shot.vx * dt;
        shot.y += shot.vy * dt;
        shot.life -= dt / 1.0;
        if (shot.life <= 0 || shot.x < -50 || shot.x > W + 50 || shot.y > H + 50) shot = null;
      }
      draw(now);
    };

    const start = () => {
      cancelAnimationFrame(raf);
      if (still || document.hidden) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const onVis = () => (document.hidden ? cancelAnimationFrame(raf) : start());
    const onMotion = () => { still = mq.matches; shot = null; draw(performance.now()); start(); };

    resize();
    start();
    window.addEventListener("resize", resize);
    document.addEventListener("visibilitychange", onVis);
    mq.addEventListener("change", onMotion);
    const ro = new ResizeObserver(resize);
    if (hostRef.current) ro.observe(hostRef.current);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      document.removeEventListener("visibilitychange", onVis);
      mq.removeEventListener("change", onMotion);
      ro.disconnect();
    };
  }, []);

  return (
    <div ref={hostRef} className="cosmos" data-cy-stars="" aria-hidden="true">
      <canvas ref={canvasRef} className="absolute inset-0" />
    </div>
  );
}
EOF
