// Cyrus studio UX (feature/cyrus-studio-ux): pure logic + ratchets for the six owner items.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { applyPatch, EMPTY_PREFS, MAX_LAYOUT_ENTRIES, MAX_OFFSET, MAX_SHOWN, nextMore, PAGE_SIZE, parseStudioPrefs, shownCount } from "../lib/cyrus/studio-prefs";
import { diffPrefs } from "../lib/cyrus/studio-prefs/client";
import { makeStars, nextShotDelay, starAlpha, starCount, STARFIELD } from "../components/cyrus/cosmos/starfield";
import { studioNavLinks } from "../components/cyrus/chrome/StudioNav";
import { buildGraph, VISIBLE_MODS } from "../components/cyrus/cosmos/graph";
import { GAMES } from "../lib/cyrus/data";
import type { Mod } from "../lib/cyrus/types";

const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");

describe("studio prefs (item 1 + 4): parse, patch, diff", () => {
  it("parses junk to defaults and clamps what it keeps", () => {
    assert.deepEqual(parseStudioPrefs(null), EMPTY_PREFS);
    assert.deepEqual(parseStudioPrefs("x"), EMPTY_PREFS);
    const p = parseStudioPrefs({ layout: { a: [1.4, 99999], b: ["x", 1], c: [1], __proto__: [1, 1], d: [NaN, 0] }, simple: "yes", more: { k: 9999, z: -3, q: "a" } });
    assert.deepEqual(p.layout, { a: [1, MAX_OFFSET] });
    assert.equal(p.simple, false);
    assert.deepEqual(p.more, { k: MAX_SHOWN });
  });
  it("caps the number of layout entries and the id length", () => {
    const big: Record<string, [number, number]> = {};
    for (let i = 0; i < MAX_LAYOUT_ENTRIES + 50; i++) big[`n${i}`] = [i, i];
    big["x".repeat(500)] = [1, 1];
    assert.equal(Object.keys(parseStudioPrefs({ layout: big }).layout).length, MAX_LAYOUT_ENTRIES);
  });
  it("applyPatch sets, removes and keeps the rest", () => {
    const base = parseStudioPrefs({ layout: { a: [1, 1], b: [2, 2] }, simple: true, more: { c: 6 } });
    const n = applyPatch(base, { layout: { a: null, d: [4, 4] }, more: { c: null, e: 12 } });
    assert.deepEqual(n.layout, { b: [2, 2], d: [4, 4] });
    assert.deepEqual(n.more, { e: 12 });
    assert.equal(n.simple, true);
    assert.equal(applyPatch(n, { simple: false }).simple, false);
  });
  it("diffPrefs sends only what changed (and removals as null)", () => {
    const synced = parseStudioPrefs({ layout: { a: [1, 1], b: [2, 2] }, more: { c: 6 } });
    const now = { layout: { a: [1, 1] as [number, number], b: [9, 9] as [number, number], n: [3, 3] as [number, number] }, simple: true, more: {} as Record<string, number> };
    assert.deepEqual(diffPrefs(synced, now), { layout: { b: [9, 9], n: [3, 3] }, more: { c: null }, simple: true });
    assert.deepEqual(diffPrefs(synced, { layout: synced.layout, simple: false, more: synced.more }), {});
  });
});

describe("load more per category (item 1)", () => {
  it("pages by PAGE_SIZE, never past what exists or MAX_SHOWN", () => {
    assert.equal(shownCount(VISIBLE_MODS, undefined, 20), VISIBLE_MODS);
    assert.equal(shownCount(VISIBLE_MODS, 6, 20), VISIBLE_MODS + 6);
    assert.equal(shownCount(VISIBLE_MODS, 99, 20), 20);
    assert.equal(nextMore(0, VISIBLE_MODS, 20), PAGE_SIZE);
    assert.equal(nextMore(PAGE_SIZE, VISIBLE_MODS, 20), PAGE_SIZE * 2);
    assert.equal(nextMore(12, VISIBLE_MODS, 20), 17); // 3 + 17 = all 20
    assert.equal(shownCount(VISIBLE_MODS, nextMore(12, VISIBLE_MODS, 20), 20), 20);
    assert.equal(shownCount(VISIBLE_MODS, nextMore(0, VISIBLE_MODS, 1000), 1000), VISIBLE_MODS + PAGE_SIZE);
    assert.ok(shownCount(VISIBLE_MODS, 10_000, 10_000) <= MAX_SHOWN);
  });
  it("the graph shows the loaded page and the '+N more' label counts what is left", () => {
    const mk = (i: number): Mod => ({ id: `m${i}`, gameId: "minecraft", category: "gameplay", name: `Mod ${i}`, summary: "", createdAt: 1000 - i, tags: [], versions: [] });
    const mods = Array.from({ length: 14 }, (_, i) => mk(i));
