content.content:
--- a/app/dashboard/cyrus/app/app.css
+++ b/app/dashboard/cyrus/app/app.css
-  min-height: 100%; position: relative; isolation: isolate;
+  /* Cut-off fix (feature/cyrus-studio-ux): .cyrus-root is a clipped, fixed-height box (overflow hidden + contain, studio.css)
+     because the studio canvas fills it; the customer app is a document, so it scrolls INSIDE that box. Before, it only
+     had min-height: 100%, grew past the box and everything below the fold was cut off with no way to reach it. */
+  height: 100%; min-height: 100%; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain;
+  position: relative; isolation: isolate;
-.cx-aura { position: absolute; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
+.cx-aura { position: fixed; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
-.cx-rail { position: sticky; top: 0; align-self: start; height: 100dvh; max-height: 100%; display: flex; flex-direction: column; gap: 4px; padding: 20px 14px; border-right: 1px solid var(--cx-line); background: color-mix(in srgb, var(--cx-bg) 70%, transparent); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); }
+.cx-rail { position: sticky; top: 0; align-self: start; height: 100%; height: 100cqh; max-height: 100%; overflow-y: auto; display: flex; flex-direction: column; gap: 4px; padding: 20px 14px; border-right: 1px solid var(--cx-line); background: color-mix(in srgb, var(--cx-bg) 70%, transparent); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); }
-  .cx-rail { order: 2; align-self: stretch; position: sticky; bottom: 0; top: auto; height: auto; z-index: 60; flex-direction: row; justify-content: space-around; padding: 6px 6px calc(6px + env(safe-area-inset-bottom)); border-right: 0; border-top: 1px solid var(--cx-line); }
+  .cx-rail { order: 2; align-self: stretch; position: sticky; bottom: 0; top: auto; height: auto; overflow: visible; z-index: 60; flex-direction: row; justify-content: space-around; padding: 6px 6px calc(6px + env(safe-area-inset-bottom)); border-right: 0; border-top: 1px solid var(--cx-line); }
-  .cx-main { order: 1; padding: 20px 16px 28px; }
+  .cx-main { order: 1; flex: 1 0 auto; padding: 20px 16px 28px; }

