"use client";
// cyrus.my top bar (feature/cyrus-studio-ux): one clean bar for the whole Cyrus host. Wordmark, the places a person goes
// (Studio, Home, New mod, Projects, Assets, Servers, Wallet, Help), tokens, account and sign out. Below 900px the links fold
// into a menu panel (button with aria-expanded, Esc closes and returns focus, links are real <a> in tab order).
// There is NO "Back to Nxeon" here: on cyrus.my a person never has to leave to find their way back, and the Nxeon-hosted
// Cyrus (nxeon.cloud/dashboard/cyrus) keeps its own back strip. The links come from lib/cyrus/host-nav.ts (pure, tested).
import { useEffect, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusTokenChip } from "@/components/cyrus-tokens";
import { hostNavLinks, isActive } from "@/lib/cyrus/host-nav";

export function HostBar({ appOn, who }: { appOn: boolean; who: string }) {
  const path = usePathname() || "";
  const [open, setOpen] = useState(false);
  const btn = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const links = hostNavLinks({ appOn });

  useEffect(() => setOpen(false), [path]);
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { setOpen(false); btn.current?.focus(); } };
    const onDown = (e: PointerEvent) => { const t = e.target as Node; if (!panel.current?.contains(t) && !btn.current?.contains(t)) setOpen(false); };
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown, true);
    return () => { window.removeEventListener("keydown", onKey); window.removeEventListener("pointerdown", onDown, true); };
  }, [open]);

  return (
    <header className="cyk-hb nx-dark-island" data-cy-hostbar>
      <div className="cyk-hb-in">
        <a className="cyk-hb-brand" href="/studio" aria-label="Cyrus studio"><CyrusWordmark height={20} /></a>
        <nav className="cyk-hb-links" aria-label="Cyrus">
          {links.main.map((l) => (
            <a key={l.key} href={l.href} aria-current={isActive(l.href, path) ? "page" : undefined}>{l.label}</a>
          ))}
        </nav>
        <div className="cyk-hb-right">
          <CyrusTokenChip compact beta={false} />
          <a className="cyk-hb-who" href={links.account.href} title={who}>{who}</a>
          <form method="post" action="/auth/logout" className="cyk-hb-out"><button type="submit">Sign out</button></form>
          <button ref={btn} type="button" className="cyk-hb-menu" aria-expanded={open} aria-controls="cyk-hb-panel" aria-label={open ? "Close menu" : "Open menu"} onClick={() => setOpen((o) => !o)}>
            <span aria-hidden /><span aria-hidden />
          </button>
        </div>
      </div>
      {open && (
        <div ref={panel} id="cyk-hb-panel" className="cyk-hb-panel">
          <nav aria-label="Cyrus menu">
            {links.main.map((l) => (
              <a key={l.key} href={l.href} aria-current={isActive(l.href, path) ? "page" : undefined}>{l.label}</a>
            ))}
            <a href={links.account.href}>Account <span className="cyk-hb-sub">{who}</span></a>
          </nav>
          <form method="post" action="/auth/logout"><button type="submit" className="cyk-hb-panel-out">Sign out</button></form>
        </div>
      )}
    </header>
  );
}
