cat > lib/cyrus/host-nav.ts <<'EOF'
// cyrus.my top bar links (feature/cyrus-studio-ux), PURE. Public short paths of the Cyrus host (lib/cyrus/app/flags.ts);
// the customer-app links exist only when that app is on. Deliberately no link back to nxeon.cloud: on cyrus.my the way
// back is Cyrus home.
export type HostLink = { key: string; label: string; href: string };

export function hostNavLinks(o: { appOn: boolean }): { main: HostLink[]; account: HostLink } {
  const main: HostLink[] = [{ key: "studio", label: "Studio", href: "/studio" }];
  if (o.appOn) {
    main.unshift({ key: "home", label: "Home", href: "/home" });
    main.push(
      { key: "new", label: "New mod", href: "/new" },
      { key: "projects", label: "Projects", href: "/projects" },
      { key: "assets", label: "Assets", href: "/assets" },
      { key: "servers", label: "Servers", href: "/servers" },
      { key: "wallet", label: "Wallet", href: "/wallet" },
    );
  }
  main.push({ key: "help", label: "Help", href: "/help" });
  return { main, account: { key: "account", label: "Account", href: o.appOn ? "/account" : "/studio" } };
}

/** Is `href` the page the browser is on? `/studio` also matches `/dashboard/cyrus` (its internal path) and `/studio/...`. */
export function isActive(href: string, path: string): boolean {
  const p = path.replace(/\/+$/, "") || "/";
  if (href === "/studio") return p === "/studio" || p.startsWith("/studio/") || p === "/dashboard/cyrus" || (p.startsWith("/dashboard/cyrus/") && !p.startsWith("/dashboard/cyrus/app"));
  if (href === "/home") return p === "/home" || p === "/dashboard/cyrus/app";
  return p === href || p.startsWith(href + "/") || p.startsWith("/dashboard/cyrus/app" + href);
}
