// The Cyrus route-segment loading state (replaces the Nxeon preloader that app/dashboard/loading.tsx drew on every Cyrus page).
// Server component, CSS only (styles: app/dashboard/cyrus/ux.css `cyk-pre*`):
//  - invisible for the first 180 ms, so a fast route never flashes it;
//  - the Cyrus mark with a thin line that sweeps under it; no spinner, no layout shift (it fills the box the page will fill);
//  - prefers-reduced-motion: the mark and a still line, no sweep;
//  - role=status with a text label, aria-live polite; it is replaced the moment the page is ready and never blocks content.
import { MARK_ARM, MARK_SWEEP, MARK_VIEWBOX } from "@/components/cyrus/icons/cyrusMark";

export function CyrusPreloader({ label = "Loading Cyrus" }: { label?: string }) {
  return (
    <div className="cyk-pre" role="status" aria-live="polite">
      <div className="cyk-pre-box">
        <svg viewBox={MARK_VIEWBOX} width={70} height={39} aria-hidden focusable="false" className="cyk-pre-mark">
          <path d={MARK_SWEEP} fill="currentColor" />
          <path d={MARK_ARM} fill="currentColor" />
        </svg>
        <span className="cyk-pre-line" aria-hidden><i /></span>
        <span className="sr-only">{label}</span>
      </div>
    </div>
  );
}
EOF
